class MixupCollate:

    def __init__(self, alpha=0.2):
        self.alpha = alpha

    def __call__(self, batch):
        X_batch = torch.stack([item[0] for item in batch])
        y_batch = torch.tensor([item[1] for item in batch], dtype=torch.long)
        lam = numpy.random.beta(self.alpha, self.alpha)
        perm = torch.randperm(X_batch.size(0))
        X_mix = lam * X_batch + (1 - lam) * X_batch[perm]
        y_mix = lam * y_batch + (1 - lam) * y_batch[perm]
        return (X_mix, y_mix)

