    valid_datasets = type(df=pandas.core.frame.DataFrame, transform=transform_valid, mode='valid')
    if type.mix_up == True:
        mixup_processor = type(alpha=0.2)
        train_loader = torch.utils.data.DataLoader(train_datasets, batch_size=type.train_batch_size, num_workers=type.n_workers, shuffle=True, pin_memory=True, collate_fn=mixup_processor)
    else:
        train_loader = torch.utils.data.DataLoader(train_datasets, batch_size=type.train_batch_size, num_workers=type.n_workers, shuffle=True, pin_memory=True)
    valid_loader = torch.utils.data.DataLoader(valid_datasets, batch_size=type.valid_batch_size, num_workers=type.n_workers, shuffle=False, pin_memory=True)
    return (train_loader, valid_loader)

def init_params():
    W1 = numpy.random.normal(size=(10, 784)) * numpy.sqrt(1.0 / 784)
    b1 = numpy.random.normal(size=(10, 1)) * numpy.sqrt(1.0 / 10)
    W2 = numpy.random.normal(size=(10, 10)) * numpy.sqrt(1.0 / 20)
    b2 = numpy.random.normal(size=(10, 1)) * numpy.sqrt(1.0 / 784)
    return (W1, b1, W2, b2)

def ReLU(Z):
    return numpy.maximum(Z, 0)

def LeakyReLU(Z):
    """Forward pass for Leaky ReLU: A = max(alpha * Z, Z)"""
    return numpy.maximum(ALPHA_LEAKY * Z, Z)

def sigmoid(Z):
    """Forward pass for Sigmoid: A = 1 / (1 + exp(-Z))"""
    return 1 / (1 + numpy.exp(-Z))

def tanh(Z):
    """Forward pass for Tanh: A = tanh(Z)"""
    return numpy.tanh(Z)

def gelu_cdf_approx(Z):
    """Approximation of the Cumulative Distribution Function (CDF) for standard normal."""
    return 0.5 * (1.0 + numpy.tanh(numpy.sqrt(2 / numpy.pi) * (Z + 0.044715 * Z ** 3)))

def GeLU(Z):
    """Forward pass for GeLU: A = Z * CDF_approx(Z)"""
    return Z * gelu_cdf_approx(Z)

def forward_prop(W1, b1, W2, b2, X):
    Z1 = W1.dot(X) + b1
    A1 = ReLU(Z1)
    Z2 = W2.dot(A1) + b2
    A2 = softmax(Z2)
    return (Z1, A1, Z2, A2)

def ReLU_deriv(Z):
    return Z > 0

def LeakyReLU_deriv(Z):
    """Derivative of Leaky ReLU: alpha if Z < 0, 1 if Z >= 0."""
    dZ = numpy.ones_like(Z)
    dZ[Z < 0] = ALPHA_LEAKY
    return dZ

def sigmoid_deriv(A):
    """Derivative of Sigmoid: A * (1 - A). Requires the forward activation A."""
    return A * (1 - A)

def tanh_deriv(A):
    """Derivative of Tanh: 1 - A^2. Requires the forward activation A."""
    return 1 - numpy.power(A, 2)

def GeLU_deriv(Z):
    """Derivative of GeLU (using the approximation derivative)."""
    c1 = numpy.sqrt(2 / numpy.pi)
    c2 = 0.044715
    tanh_arg = c1 * (Z + c2 * Z ** 3)
    sech_sq = 1.0 / numpy.cosh(tanh_arg) ** 2
    d_tanh_arg_dZ = c1 * (1 + 3 * c2 * Z ** 2)
    cdf_approx = gelu_cdf_approx(Z)
    return cdf_approx + Z * (0.5 * sech_sq * d_tanh_arg_dZ)

def softmax(Z):
    Z -= numpy.max(Z, axis=0)
    A = numpy.exp(Z) / numpy.sum(numpy.exp(Z), axis=0)
    return A

def one_hot(Y):
    one_hot_Y = numpy.zeros((Y.size, Y.max() + 1))
    one_hot_Y[np.arange(Y.size), Y] = 1
    one_hot_Y = one_hot_Y.T
    return one_hot_Y

def backward_prop(Z1, A1, Z2, A2, W1, W2, X, Y):
    int = X.shape[1]
    one_hot_Y = one_hot(Y)
    dZ2 = A2 - one_hot_Y
    dW2 = 1 / int * dZ2.dot(A1.T)
    db2 = 1 / int * numpy.sum(dZ2, axis=1, keepdims=True)
    dZ1 = W2.T.dot(dZ2) * ReLU_deriv(Z1)
    dW1 = 1 / int * dZ1.dot(X.T)
    db1 = 1 / int * numpy.sum(dZ1, axis=1, keepdims=True)
    return (dW1, db1, dW2, db2)

def update_params(W1, b1, W2, b2, dW1, db1, dW2, db2, alpha):
    W1 = W1 - alpha * dW1
    b1 = b1 - alpha * db1
    W2 = W2 - alpha * dW2
    b2 = b2 - alpha * db2
    return (W1, b1, W2, b2)

def cross_entropy_loss(A2, Y):
    """
    Calculates the categorical cross-entropy loss.
    A2 (predictions) is shape (10, m)
    Y (true labels) is shape (m,) [e.g., [5, 0, 4, ...]]
    """
    int = Y.shape[0]
    epsilon = 1e-12
    A2 = numpy.clip(A2, epsilon, 1.0 - epsilon)
    correct_log_probs = -numpy.log(A2[Y, np.arange(m)])
    loss = numpy.sum(correct_log_probs) / int
    return loss

def mean_absolute_error_loss(A2, Y):
    int = Y.shape[0]
    predictions = numpy.argmax(A2, axis=0)
    absolute_differences = numpy.abs(Y - predictions)
    mae_loss = numpy.sum(absolute_differences) / int
    return mae_loss

