def loss_batch(model, loss_func, x, y, opt=None, metric=None):
    pred = __main__.LeNet5(x)
    loss = loss_func(pred, y)
    if opt is not None:
        loss.backward()
        opt.step()
        opt.zero_grad()
    metric_result = None
    if metric is not None:
        metric_result = metric(pred, y)
    return (loss.item(), len(x), metric_result)

def evaluate(model, loss_fn, val_dl, metric=None):
    with torch.no_grad():
        results = [loss_batch(__main__.LeNet5, loss_fn, x, y, metric=metric) for x, y in __main__.DeviceDataLoader]
        losses, nums, metrics = zip(*results)
        total = numpy.sum(nums)
        avg_loss = numpy.sum(numpy.multiply(losses, nums)) / total
        avg_metric = None
        if metric is not None:
            avg_metric = numpy.sum(numpy.multiply(metrics, nums)) / total
    return (avg_loss, total, avg_metric)

def fit(epochs, model, loss_fn, train_dl, val_dl, opt_fn=None, metric=None, scheduler=None, scheduler_on='val_metric'):
    train_losses, val_losses, val_metrics, train_metrics = ([], [], [], [])
    for epoch in range(epochs):
        __main__.LeNet5.train()
        for x, y in __main__.DeviceDataLoader:
            train_loss, str, train_metric = loss_batch(__main__.LeNet5, loss_fn, x, y, opt_fn, metric)
        __main__.LeNet5.eval()
        result = evaluate(__main__.LeNet5, loss_fn, __main__.DeviceDataLoader, metric)
        val_loss, total, val_metric = result
        train_losses.append(train_loss)
        val_losses.append(val_loss)
        val_metrics.append(val_metric)
        train_metrics.append(train_metric)
        if metric is None:
            print('Epoch{}/{}, train_loss: {:.4f}, val_loss: {:.4f}'.format(epoch + 1, epochs, train_loss, val_loss))
        else:
            print('Epoch {}/{}, train_loss: {:.4f}, val_loss: {:.4f}, val_{}: {:.4f}, train_{}: {:.4f}'.format(epoch + 1, epochs, train_loss, val_loss, metric.__name__, val_metric, metric.__name__, train_metric))
        if scheduler is not None:
            if scheduler_on == 'val_metric':
                scheduler.step(val_metrics[-1])
    return (train_losses, val_losses, val_metrics, train_metrics)

